// Generate small runtime inventories; core and creator never import the compiler at runtime.
// First build core when its public contracts changed, then run this script and format outputs.
import { writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'
import { macosComponentCapabilities } from '../packages/create-mavis/templates/macos/scripts/portable/component-capabilities.mjs'

export function macosCapabilityFiles(capabilities) {
  const payload = JSON.stringify(capabilities, null, 2)
  const header =
    '// Generated by scripts/sync-macos-capabilities.mjs from the portable compiler registry.\n// Source inventory only; registration is not runtime validation. Do not edit.\n'
  return {
    'packages/core/src/macos-capabilities.generated.ts': `${header}export const macosCapabilities = ${payload} as const\n`,
    'packages/create-mavis/src/macos-capabilities.generated.mjs': `${header}export const macosCapabilities = ${payload}\n`,
  }
}
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const root = resolve(import.meta.dirname, '..')
  const { componentNames } = await import(pathToFileURL(join(root, 'packages/core/dist/index.js')))
  const { componentProps, spanProps, themeProviderProps, platformProps } = await import(
    pathToFileURL(join(root, 'packages/core/dist/vue/index.js'))
  )
  const props = {
    ...componentProps,
    MSpan: spanProps,
    MThemeProvider: themeProviderProps,
    MPlatform: platformProps,
  }
  const data = macosComponentCapabilities(componentNames, (name) => Object.keys(props[name] ?? {}))
  for (const [name, source] of Object.entries(macosCapabilityFiles(data)))
    writeFileSync(join(root, name), source)
  console.log(`Generated Mac inventory for ${Object.keys(data.components).length} components.`)
}
